from itertools import product

def check_condition(P, n):
    """Checks if P(k) is a multiple of n for k=1 to n."""
    for k in range(1, n + 1):
        if P(k) % n != 0:
            return False
    return True

def solve_case(n):
    min_W = float('inf')
    best_polynomials = []

    # The polynomial degree is n. Coefficients are a_n, a_{n-1}, ..., a_0.
    # a_n must be 1 or -1. Other coefficients are -1, 0, or 1.

    # Since we search systematically, we iterate over all combinations
    # of coefficients allowed by the degree n.

    # Possible values for coefficients: {-1, 0, 1}
    # a_n is fixed to {1, -1}

    # We iterate over all possibilities for a_{n-1} down to a_0.

    # Since the degree is n, we have n+1 coefficients (a_0 to a_n).
    # a_n is non-zero. We iterate over 3^n possibilities for the remaining n coefficients.

    for sign_an in [1, -1]:
        # Iterate over all combinations of (a_{n-1}, ..., a_0) where each is in {-1, 0, 1}
        # There are 3^n combinations for the lower n coefficients.
        for coeffs_tuple in product([-1, 0, 1], repeat=n):

            # Construct the full coefficient list: [a_0, a_1, ..., a_n]
            coeffs = list(coeffs_tuple) + [sign_an]
            coeffs.reverse() # Now coeffs = [a_n, a_{n-1}, ..., a_0]

            # W is the number of non-zero coefficients
            W = sum(1 for c in coeffs if c != 0)

            if W >= min_W:
                continue

            # Define the polynomial P(x)
            def P(x):
                y = 0
                for i in range(n + 1):
                    # Coeffs is indexed such that coeffs[i] is a_{n-i}
                    # The power is n-i.
                    power = n - i
                    y += coeffs[i] * (x**power)
                return y

            if check_condition(P, n):
                if W < min_W:
                    min_W = W
                    best_polynomials = [tuple(coeffs)]
                elif W == min_W:
                    best_polynomials.append(tuple(coeffs))

    return min_W, best_polynomials

# --- Cases ---
N_values = [2, 3, 4]
results = {}
for n in N_values:
    min_W, polynomials = solve_case(n)
    results[n] = (min_W, polynomials)
    print(f"--- Results for n={n} ---")
    print(f"Minimum W found: {min_W}")
    print(f"Polynomials (Coefficients [a_n, a_{n-1}, ..., a_0]): {polynomials}")

